#[derive(Clone, Copy, Debug, PartialEq)]
pub struct Extent {
    pub width: f32,
    pub height: f32,
}

impl Extent {
    /// The byte length of an [`Extent`]
    pub const SIZE: usize = 8;

    /// The alignment of an array of an [`Extent`]: its largest scalar's size
    pub const ALIGNMENT: Alignment = Alignment::Four;

    /// Reads an [`Extent`] from the start of `bytes`
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if `bytes` are shorter than [`Self::SIZE`].
    pub fn read(bytes: &[u8]) -> Result<Self, DecodeError> {
        match bytes.first_chunk() {
            Some(bytes) => Ok(Self::from_bytes(bytes)),
            None => Err(DecodeError::OutOfRange {
                position: 0,
                byte_length: 8,
                available: bytes.len(),
            }),
        }
    }

    /// Reads an [`Extent`] from its bytes, such as those of an array of them
    #[must_use]
    #[allow(clippy::trivially_copy_pass_by_ref)]
    pub fn from_bytes(bytes: &[u8; 8]) -> Self {
        Self {
            width: f32::from_le_bytes(bytes[0..4].try_into().unwrap_or_default()),
            height: f32::from_le_bytes(bytes[4..8].try_into().unwrap_or_default()),
        }
    }

    #[must_use]
    pub fn to_bytes(self) -> [u8; 8] {
        let mut bytes = [0; Self::SIZE];
        bytes[0..4].copy_from_slice(&self.width.to_le_bytes());
        bytes[4..8].copy_from_slice(&self.height.to_le_bytes());

        bytes
    }

    /// Writes [`Extent`]s one after another, as an array of them holds them
    #[must_use]
    pub fn array_to_bytes(items: &[Self]) -> Vec<u8> {
        let mut bytes = Vec::with_capacity(items.len() * Self::SIZE);
        for item in items {
            bytes.extend_from_slice(&item.to_bytes());
        }

        bytes
    }
}

/// A message without a version, whose second revision appends `count`
#[derive(Clone, Copy, Debug)]
pub struct Sample<'a> {
    bytes: &'a [u8],
}

impl<'a> Sample<'a> {
    const LAYOUT: TableLayout = TableLayout::DEFAULT;

    /// Reads a [`Sample`] from `bytes`
    pub const fn new(bytes: &'a [u8]) -> Self {
        Self { bytes }
    }

    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn key(&self) -> Result<u32, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        let position = reader.root_offset(0)?;
        reader.get_u32(position)
    }

    /// `7` when the table doesn't hold it, as [`Self::has_count`] tells
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field lies outside the bytes.
    pub fn count(&self) -> Result<u16, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        if reader.root_offset(0)? < 8 {
            return Ok(7);
        }

        let position = reader.root_offset(1)?;
        if position == 0 {
            return Ok(7);
        }

        reader.get_u16(position)
    }

    /// Whether the table holds `count`
    ///
    /// # Errors
    ///
    /// Returns a [`DecodeError`] if the field's offset lies outside the bytes.
    pub fn has_count(&self) -> Result<bool, DecodeError> {
        let reader = TableReader::new(self.bytes, Self::LAYOUT);
        if reader.root_offset(0)? < 8 {
            return Ok(false);
        }

        let position = reader.root_offset(1)?;
        Ok(position != 0)
    }
}

/// The fields of a [`Sample`], to write
#[derive(Clone, Debug)]
pub struct SampleFields {
    pub key: u32,
    pub count: u16,
}

impl SampleFields {
    /// Writes a [`Sample`] with every field
    ///
    /// # Errors
    ///
    /// Returns a [`BuildError`] if it's longer than its offset type, `uint32`, addresses.
    pub fn serialize(&self) -> Result<Vec<u8>, BuildError> {
        let mut bytes = TableWriter::table_bytes(2, Sample::LAYOUT, 14)?;

        let mut fixed = [0; 14];
        fixed[0..4].copy_from_slice(&8_u32.to_le_bytes());
        fixed[4..8].copy_from_slice(&12_u32.to_le_bytes());
        fixed[8..12].copy_from_slice(&self.key.to_le_bytes());
        fixed[12..14].copy_from_slice(&self.count.to_le_bytes());
        bytes.extend_from_slice(&fixed);

        Ok(bytes)
    }
}

